def solve(workloads, k):
    if not workloads:
        return 0
    if k >= len(workloads):
        return max(workloads)
    def feasible(max_load):
        workers = 1
        curr_load = 0
        for w in workloads:
            if curr_load + w > max_load:
                workers += 1
                curr_load = w
                if workers > k:
                    return False
            else:
                curr_load += w
        return True
    low, high = max(workloads), sum(workloads)
    ans = high
    while low <= high:
        mid = (low + high) // 2
        if feasible(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans
